plan={'revision':'room-v2','originalVideoSeconds':728.316667,'originalMasterSha256':'023ca35a572c9b9d0902c3b3c9c88b06d24e6b5a751b521bd1707769fc768627','scope':'same product extended through 8 tool examples; interactive browser room; actual commands/prompts/settings; no upload','priority':'game interaction quality before new audio generation','originalNarrationPreserved':True,'order':'original30 sections retained; actual demonstrations inserted directly beside their relevant claims','estimatedNewKoreanCharacters':sum(len(x[3]) for x in adds),'currentState':'script + execution records prepared; SSD true inference pending; root owns playable game and URL/capture','newTtsAuthorizedButNotStarted':True,'resourcePolicy':'Qwen GPU only after parent GPU lease admission; keep original PCM and masters','noClaimOfExecution':['NovelAI','new character LoRA training','Aseprite','Pixel Snapper','Agent Sprite Forge external image-to-video API'],'humanReview':False,'scenes':full}
